async function loadHivePatterns(docsDir) {
  const patternsPath = path4.join(docsDir, "META_PATTERNS.md");
  try {
    const content = await fs3.readFile(patternsPath, "utf-8");
    const additionalPatterns = parseMetaPatterns(content);
    return [...KNOWN_PATTERNS, ...additionalPatterns];
  } catch (e) {
    tridentLog("WARN", "hive-loader", `Failed to load hive patterns: ${e instanceof Error ? e.message : String(e)}`);
    return KNOWN_PATTERNS;
  }
}
async function enrichWithHiveKnowledge(findings, docsDir) {
  const patterns = await loadHivePatterns(docsDir);
  return findings.map((finding) => {
    for (const pattern of patterns) {
      const evidenceLower = finding.evidence.toLowerCase();
      const patternLower = pattern.pattern.toLowerCase();
      const descLower = finding.description.toLowerCase();
      let matchesEvidence = false;
      let matchesDescription = false;
      try {
        const re = new RegExp(patternLower.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"), "i");
        matchesEvidence = re.test(evidenceLower);
        matchesDescription = re.test(descLower);
      } catch (e) {
        console.error("[HiveLoader] error:", e);
        matchesEvidence = evidenceLower.includes(patternLower);
        matchesDescription = descLower.includes(patternLower);
        return finding;
      }
      if (matchesEvidence || matchesDescription) {
        const patternWords = patternLower.split(/[\s._-]+/).filter((w) => w.length >= 3);
        const descWords = descLower.split(/[\s._-]+/).filter((w) => w.length >= 3);
        const sharedWords = patternWords.filter((pw) => descWords.some((dw) => dw === pw));
        if (sharedWords.length < 3 && patternWords.length >= 3)
          continue;
        if (sharedWords.length >= 3 || patternWords.length < 3) {
          return {
            ...finding,
            correction: `${finding.correction}

**Cross-Project Evidence:** This pattern occurred ${pattern.occurrences} times across: ${pattern.projects.join(", ")}.
**Proven Fix:** ${pattern.fix}
**Source:** ${pattern.evidence}`
          };
        }
      }
    }
    if (finding) {}
    return finding;
  });
}
function parseMetaPatterns(content) {
  const patterns = [];
  let sections;
  try {
    sections = content.split(/### CATEGORY \d+: /);
  } catch {
    tridentLog("WARN", "hive-loader", "Regex split failed in parseMetaPatterns, skipping");
    return [];
  }
  for (const section of sections) {
    const nameMatch = section.match(/^([^\n]+)/);
    const countMatch = section.match(/Occurrences:?\s*(\d+)/i) || section.match(/(\d+)\s+(?:occurrence|bugs|instances)/i);
    const projectsMatch = section.match(/Projects?:?\s*(.+?)(?:\n|$)/i);
    const fixMatch = section.match(/Fix:?\s*(.+?)(?:\n|$)/i) || section.match(/Solution:?\s*(.+?)(?:\n|$)/i);
    if (nameMatch) {
      patterns.push({
        pattern: nameMatch[1].trim().substring(0, 60),
        occurrences: countMatch ? parseInt(countMatch[1]) : 1,
        projects: projectsMatch ? [projectsMatch[1].trim()] : ["unknown"],
        fix: fixMatch ? fixMatch[1].trim() : "See META_PATTERNS.md for proven fix",
        evidence: section.trim().substring(0, 200)
      });
    }
  }
  return patterns;
}

// src/audit-engine/fix-prioritizer.ts
function prioritizeFixes(result) {
  const phases = [];
  const allFindings = [...result.findings];
  const phaseDefs = [
    {
      phase: 1,
      name: "Build Chain",
      description: "Fix build system first \u2014 must build before anything else",
      layers: ["R0"],
      afterFixCommands: ["npm run build", "npm run build:check"],
      blocksPhases: [2, 3, 4, 5, 6, 7],
      scoreGroup: 15
    },
    {
      phase: 2,
      name: "Deployment & Config",
      description: "Enable container deployment \u2014 must deploy before testing",
      layers: ["R5", "R7"],
      afterFixCommands: ["docker run --rm opencode-test:1.14.34 ls"],
      blocksPhases: [3, 4, 5, 6],
      scoreGroup: 15
    },
    {
      phase: 3,
      name: "Hook Contract",
      description: "Fix hook implementations \u2014 must work before testing behavior",
      layers: ["R1", "R12"],
      afterFixCommands: ["npm run build", "deploy to container", 'TUI: "who are you"'],
      blocksPhases: [4, 6],
      scoreGroup: 15
    },
    {
      phase: 4,
      name: "Core Logic",
      description: "Fix state machines and invocation \u2014 core behavior must be correct",
      layers: ["R2", "R10", "R11"],
      afterFixCommands: ["npm run build", "npm test (if available)"],
      blocksPhases: [5, 6],
      scoreGroup: 12
    },
    {
      phase: 5,
      name: "Robustness",
      description: "Fix error handling and runtime contract \u2014 make it resilient",
      layers: ["R3", "R4", "R9"],
      afterFixCommands: ["npm run build", "npm run build:check"],
      blocksPhases: [6, 7],
      scoreGroup: 10
    },
    {
      phase: 6,
      name: "Quality",
      description: "Fix dependency integrity, source hygiene",
      layers: ["R6", "R8"],
      afterFixCommands: ["npm run build:check"],
      blocksPhases: [7],
      scoreGroup: 5
    },
    {
      phase: 7,
      name: "Self-Audit",
      description: "Re-audit to verify score improved",
      layers: [],
      afterFixCommands: ["Re-run Trident v4.3 audit"],
      blocksPhases: [],
      scoreGroup: 0
    }
  ];
  for (const def of phaseDefs) {
    const phaseFindings = allFindings.filter((f) => def.layers.includes(f.layer));
    const critical = phaseFindings.filter((f) => f.severity === "CRITICAL").length;
    const high = phaseFindings.filter((f) => f.severity === "HIGH").length;
    const medium = phaseFindings.filter((f) => f.severity === "MEDIUM").length;
    let scoreImprovement = 0;
    for (const f of phaseFindings) {
      const evidenceFactor = f.evidenceSuppressed ? 0.1 : 1;
      const baseScore = f.severity === "CRITICAL" ? def.scoreGroup : f.severity === "HIGH" ? 8 : f.severity === "MEDIUM" ? 3 : 1;
      scoreImprovement += Math.round(baseScore * f.confidence * evidenceFactor);
    }
    if (phaseFindings.length > 0 || def.phase === 7) {
      phases.push({
        phase: def.phase,
        name: def.name,
        description: def.description,
        layers: def.layers,
        findings: phaseFindings,
        scoreImprovement: def.phase === 7 ? 5 : scoreImprovement,
        afterFixCommands: def.afterFixCommands,
        blocksPhases: def.blocksPhases
      });
    }
  }
  return phases;
}
function generateFixSummary(phases, currentScore) {
  let summary = `## FIX PRIORITIZATION \u2014 Dependency-Ordered Action Plan

`;
  summary += `**Current Score:** ${currentScore}/100
`;
  summary += `**Phases:** ${phases.length} (fix in order \u2014 each phase unblocks the next)

`;
  summary += `---

`;
  for (const phase of phases) {
    const critical = phase.findings.filter((f) => f.severity === "CRITICAL").length;
    const high = phase.findings.filter((f) => f.severity === "HIGH").length;
    const medium = phase.findings.filter((f) => f.severity === "MEDIUM").length;
    summary += `### Phase ${phase.phase}: ${phase.name}
`;
    summary += `**${phase.description}**

`;
    summary += `| Severity | Count | Score Fix |
`;
    summary += `|----------|-------|----------|
`;
    if (critical > 0)
      summary += `| CRITICAL | ${critical} | +${critical * 15} |
`;
    if (high > 0)
      summary += `| HIGH | ${high} | +${high * 8} |
`;
    if (medium > 0)
      summary += `| MEDIUM | ${medium} | +${medium * 3} |
`;
    summary += `
**Total Score Improvement:** +${phase.scoreImprovement}
`;
    summary += `**After fixing, run:** \`${phase.afterFixCommands.join(" && ")}\`

`;
    if (phase.findings.length > 0) {
      for (const f of phase.findings) {
        summary += `- [${f.layer}] \`${f.file}:${f.line}\` \u2014 ${f.description.substring(0, 100)}
`;
      }
    } else if (phase.phase === 7) {
      summary += `- Re-run audit with: "audit this project"
`;
      summary += `- Compare scores \u2014 should be \u2265 80 (NEAR RUNTIME GRADE or better)
`;
    }
    summary += `
`;
  }
  summary += `---
`;
  summary += `**Target:** Complete phases 1-7 to achieve RUNTIME GRADE (95+).
`;
  summary += `Each phase unblocks the next \u2014 follow the order exactly.
`;
  return summary;
}

