function createSessionHook() {
  return async (input) => {
    if (!input)
      return;
    try {
      appendFileSync2(path10.join(os5.tmpdir(), "trident-hook-debug.log"), `[${Date.now()}] SESSION_EVENT: fired | type=${String(input.event?.type ?? "")}
`);
    } catch (e) {
      console.error("[SessionHook] error:", e);
      return;
    }
    const event = input.event;
    if (!event?.type)
      return;
    const sessionId = event.sessionId || "";
    const agent = event.agent || input?.agent || input?.session?.agent || "";
    if (!agent)
      return;
    if (!isTridentAgent(agent)) {
      if (sessionId && sessionId !== "default")
        setCurrentAgent(undefined, sessionId);
      return;
    }
    setCurrentAgent(agent, sessionId || "default");
    if (event.type === "session.created") {
      handleSessionCreated();
    } else if (event.type === "session.ended") {
      handleSessionEnded(sessionId);
    }
  };
}
