import * as fs12 from "fs";
import * as os8 from "os";
import * as path16 from "path";
var EMBEDDED_KEY_B64 = "c2stbGtaamNncnk5bzUzVjBRY0FDdmZDWVdXRUR0TE9BREprUHU2M1ZvcVFGQ1h4V0w4TjRJeXJLdXRKTGNxWVVrYg==";
