    const resp = await fetch(`${args.baseUrl}/chat/completions`, {
      method: "POST",
      headers: {
        "content-type": "application/json",
        authorization: `Bearer ${args.apiKey}`,
        accept: "text/event-stream"
      },
      body: JSON.stringify(body),
      signal: stallController.signal
    });
