    const nameMatch = typeDef.match(/interface\s+(\w+)/);
    const name = nameMatch ? nameMatch[1] : `Type ${i + 1}`;
    const kind = name.includes("Input") ? "Input" : name.includes("Output") ? "Output" : name.includes("Pipeline") ? "Container" : "Definition";
