function buildTestSpecificationsSection(tests) {
  let out = `## Test Specifications

`;
  out += "Test cases generated from threat-defense pairs. Each defense has ";
  out += "a NEGATIVE test (simulates the attack, expects FAIL) and a POSITIVE ";
  out += "test (simulates a legitimate case, expects PASS). Unmatched threats ";
  out += `produce BLIND-SPOT tests.

`;
  const negTests = tests.filter((t) => t.name.startsWith("NEG:"));
  const posTests = tests.filter((t) => t.name.startsWith("POS:"));
  const blindTests = tests.filter((t) => t.name.startsWith("BLIND:"));
  out += `**Total tests:** ${tests.length} `;
  out += `(${negTests.length} negative, ${posTests.length} positive, ${blindTests.length} blind-spot)

`;
  out += `### Test Summary

`;
  out += `| # | Name | Category | Expected | Defeat Vector |
`;
  out += `|---|------|----------|----------|---------------|
`;
  for (let i = 0;i < tests.length; i++) {
    const t = tests[i];
    out += `| ${i + 1} | ${t.name.substring(0, 50)} | ${t.category} | ${t.expectedResult} | ${t.defeatVector.substring(0, 60)} |
`;
  }
  out += `
`;
  out += `### Test Details

`;
  for (const t of tests) {
    out += `#### ${t.name}

`;
    out += `- **Category:** ${t.category}
`;
    out += `- **Expected Result:** ${t.expectedResult}
`;
    out += `- **Defeat Vector:** ${t.defeatVector}
`;
    if (t.expectedProvenance) {
      out += `- **Expected Provenance:** ${t.expectedProvenance}
`;
    }
    out += `- **Expected Details:**
`;
    for (const detail of t.expectedDetail) {
      out += `  - ${detail}
`;
    }
    out += `- **Input:**
`;
    out += "```json\n";
    out += JSON.stringify(t.input, null, 2);
    out += "\n```\n\n";
    out += `**Execution Steps:**
`;
    out += `1. Prepare test environment with the input data shown above
`;
    out += `2. Run the defense check method against the input
`;
    out += `3. Capture the check output and any findings produced
`;
    out += `4. Compare the output against the expected result: ${t.expectedResult}
`;
    out += `5. Record the test result (PASS/FAIL) and any findings

`;
    out += `**Pass/Fail Criteria:**
`;
    out += `- **PASS:** The check produces the expected result (${t.expectedResult})
`;
    out += `- **FAIL:** The check produces a different result than expected
`;
    out += `- **ERROR:** The check throws an exception or crashes

`;
    if (t.expectedDetail.length > 0) {
      out += `**Expected Findings:**
`;
      for (const detail of t.expectedDetail) {
        out += `- ${detail}
`;
      }
      out += `
`;
    }
    out += `**Expected Output:**
`;
    const expectedSeverity = t.expectedResult === "FAIL" ? "CRITICAL" : "NONE";
    const expectedRule = t.name.replace(/^(NEG:|POS:|BLIND:)\s*/, "");
    if (t.expectedResult === "FAIL") {
      out += `- Finding: { severity: "${expectedSeverity}", rule: "${expectedRule}" }
`;
      if (t.expectedDetail.length > 0) {
        out += `- Evidence: "${t.expectedDetail[0]}"
`;
      }
      out += `- Verdict: FAIL \u2014 the defense check detected the threat in the input

`;
    } else if (t.expectedResult === "PASS") {
      out += `- Finding: (none \u2014 no violation detected)
`;
      out += `- Verdict: PASS \u2014 the legitimate input does not trigger the defense

`;
    } else {
      out += `- Verdict: ${t.expectedResult}

`;
    }
    const categoryDescriptions = {
      NEGATIVE: "Negative test \u2014 simulates an attack/defeat vector. The check should FAIL (detect the threat). If the check PASSES, the defense is not working.",
      POSITIVE: "Positive test \u2014 simulates a legitimate case. The check should PASS (no threat detected). If the check FAILS, the defense is too aggressive (false positive).",
      "BLIND-SPOT": "Blind-spot test \u2014 threat has no catalog defense. Documents the gap for manual review."
    };
    const catDesc = categoryDescriptions[t.category] || "Test case for the defense check method.";
    out += `**Category Explanation:** ${catDesc}

`;
  }
  return out;
}
