function buildVerificationMatrixSection(defenses, threats) {
  let out = `## Verification Matrix

`;
  out += "Evidence domain defenses and their verification requirements. ";
  out += "Each defense maps to a verification check that must pass before ";
  out += `the build is considered complete.

`;
  const evidenceDefenses = defenses.filter((d) => d.domain === "evidence");
  if (evidenceDefenses.length === 0) {
    out += `No evidence domain defenses \u2014 verification matrix is empty.

`;
    return out;
  }
  out += `| # | Defense Rule | Check Method | Order | Thresholds | Verification |
`;
  out += `|---|-------------|-------------|-------|------------|--------------|
`;
  for (let i = 0;i < evidenceDefenses.length; i++) {
    const d = evidenceDefenses[i];
    const thresholds = `pass ${formatThreshold(d.thresholds.passThreshold)}, warn ${formatThreshold(d.thresholds.warnThreshold)}, fail ${formatThreshold(d.thresholds.failThreshold)}`;
    const verification = `Run ${d.checkMethod} and verify result ${d.thresholds.failThreshold.operator} ${d.thresholds.failThreshold.value}`;
    out += `| ${i + 1} | ${d.rule} | ${d.checkMethod} | ${d.analysisOrder} | ${thresholds} | ${verification} |
`;
  }
  out += `
`;
  const evidenceThreats = threats.filter((t) => evidenceDefenses.some((d) => {
    const threatKey = t.pattern.toLowerCase();
    const threatKeyHyphen = threatKey.replace(/_/g, "-");
    const mappedPattern = THREAT_PATTERN_DIRECT_MAP[threatKey];
    return d.threatPattern === t.pattern || d.threatPattern === threatKeyHyphen || mappedPattern !== undefined && mappedPattern === d.threatPattern;
  }));
  if (evidenceThreats.length > 0) {
    out += `### Evidence Threats Requiring Verification

`;
    for (const t of evidenceThreats) {
      out += `- **${t.pattern}** (${t.severity}, Score: ${t.score})
`;
      if (t.defeatVectors.length > 0) {
        out += `  - Defeat vector: ${t.defeatVectors[0]}
`;
      }
      const sampleFindings = t.findings.slice(0, 5);
      if (sampleFindings.length > 0) {
        out += `  - Sample findings (${t.findings.length} total):
`;
        for (const f of sampleFindings) {
          if (f.file && f.line) {
            out += `    - \`${f.file}:${f.line}\` \u2014 ${f.description}
`;
          } else {
            out += `    - ${f.description}
`;
          }
        }
        if (t.findings.length > 5) {
          out += `    - _... and ${t.findings.length - 5} more_
`;
        }
      }
    }
    out += `
`;
  }
  out += `### Full Coverage Matrix

`;
  out += "Maps every threat to every evidence defense to show which threats ";
  out += `are covered and which are not.

`;
  out += `| Threat | Severity | Defense | Covered? | Check Method |
`;
  out += `|--------|----------|---------|----------|-------------|
`;
  for (const t of threats) {
    let hasCoverage = false;
    for (const d of evidenceDefenses) {
      const covered = (() => {
        const threatKey = t.pattern.toLowerCase();
        const threatKeyHyphen = threatKey.replace(/_/g, "-");
        const mappedPattern = THREAT_PATTERN_DIRECT_MAP[threatKey];
        return d.threatPattern === t.pattern || d.threatPattern === threatKeyHyphen || mappedPattern !== undefined && mappedPattern === d.threatPattern;
      })();
      if (covered) {
        hasCoverage = true;
        out += `| ${t.pattern.substring(0, 40)} | ${t.severity} | ${d.rule} | YES | \`${d.checkMethod}\` |
`;
      }
    }
    if (!hasCoverage) {
      out += `| ${t.pattern.substring(0, 40)} | ${t.severity} | \u2014 | NO (general domain) | \u2014 |
`;
    }
  }
  out += `
`;
  out += `### Evidence Chain Requirements

`;
  out += "Each evidence defense contributes to the evidence chain. The chain ";
  out += `must be unbroken from threat detection to verification.

`;
  out += `| Step | Defense | Input | Output | Chain Link |
`;
  out += `|------|---------|-------|--------|-----------|
`;
  for (let i = 0;i < evidenceDefenses.length; i++) {
    const d = evidenceDefenses[i];
    const link = i === 0 ? "Initial detection" : `Links from step ${i}`;
    out += `| ${i + 1} | ${d.rule} | ${d.inputs.join(", ") || "(none)"} | ${d.outputs.join(", ") || "(none)"} | ${link} |
`;
  }
  out += `
`;
  return out;
}
