  const details = [];
  if (!mainSessionId) {
    const r2 = {
      probe: "P2",
      verdict: false,
      results: {},
      details: ["SKIPPED: no main session ID available in this runtime"],
      at: new Date().toISOString(),
      skipped: true,
      skipReason: "no main session ID"
    };
    writeProbeArtifact(r2);
    return r2;
  }
