function extractSection(doc3, sectionTitle) {
  const lines = doc3.split(`
`);
  const titleLower = sectionTitle.toLowerCase().trim();
  let startIndex = -1;
  let headingLevel = 0;
  for (let i = 0;i < lines.length; i++) {
    const line = lines[i];
    const headingMatch = line.match(/^(#{1,6})\s+(.+)$/);
    if (headingMatch) {
      const level = headingMatch[1].length;
      const title = headingMatch[2].replace(/^\d+\.\s*/, "").trim().toLowerCase();
      if (title === titleLower) {
        startIndex = i;
        headingLevel = level;
        break;
      }
    }
  }
  if (startIndex === -1) {
    return "";
  }
  const result = [];
  for (let i = startIndex;i < lines.length; i++) {
    if (i > startIndex) {
      const line = lines[i];
      const headingMatch = line.match(/^(#{1,6})\s+/);
      if (headingMatch && headingMatch[1].length <= headingLevel) {
        break;
      }
    }
    result.push(lines[i]);
  }
  return result.join(`
`);
}
