async function runInternalLLMLoop(brief, analysis, strategy, options2) {
  let generatedSpec = "";
  let lastFeedback = "";
  for (let iter = 1;iter <= options2.maxIterations; iter++) {
    tridentLog("INFO", "shared-llm-loop", `Iteration ${iter}/${options2.maxIterations}`);
    try {
      generatedSpec = await generateSpecViaLLM(brief, lastFeedback || undefined, options2.useSplit, options2.systemOverride);
    } catch (llmErr) {
      tridentLog("ERROR", "shared-llm-loop", `LLM failed iter ${iter}: ${llmErr instanceof Error ? llmErr.message : String(llmErr)}`);
      if (iter === options2.maxIterations)
        throw llmErr;
      continue;
    }
    tridentLog("INFO", "shared-llm-loop", `Iter ${iter}: ${generatedSpec.split(`
`).length} lines`);
    if (options2.skipQualityChecks || !analysis)
      break;
    const deepening = runDeepeningChecks(generatedSpec, analysis);
    const audit2 = runCrossSectionAudit(generatedSpec, analysis, strategy);
    const rejectCount = (deepening.gaps || []).filter((g2) => g2.severity === "REJECT").length + countRejectAuditIssues(audit2);
    const totalIssues = (deepening.gaps || []).length + audit2.issueCount;
    const passRate = totalIssues > 0 ? 1 - rejectCount / Math.max(totalIssues, 1) : 1;
    if (deepening.passed && audit2.passed) {
      tridentLog("INFO", "shared-llm-loop", `Iter ${iter}: ALL CHECKS PASSED`);
      break;
    }
    if (rejectCount === 0 && passRate >= 0.85) {
      tridentLog("INFO", "shared-llm-loop", `Iter ${iter}: 85%+ quality (0 REJECT issues, ${totalIssues} WARN) \u2014 accepting`);
      break;
    }
    const parts = [];
    if (!deepening.passed)
      parts.push(formatDeepeningFeedback(deepening));
    if (!audit2.passed)
      parts.push(formatAuditFeedback(audit2));
    lastFeedback = parts.join(`

`);
    tridentLog("WARN", "shared-llm-loop", `Iter ${iter}: ${deepening.gaps.length} gaps, ${audit2.issueCount} issues, ${rejectCount} REJECT`);
  }
  return generatedSpec;
}

