function extractKeyTerms(requirements) {
  const STOP_WORDS = new Set([
    "the",
    "and",
    "for",
    "with",
    "that",
    "this",
    "from",
    "are",
    "was",
    "were",
    "have",
    "has",
    "will",
    "can",
    "not",
    "but",
    "all",
    "any",
    "new",
    "use",
    "must",
    "should",
    "system",
    "tool",
    "agent",
    "engine",
    "layer",
    "phase",
    "step",
    "section",
    "build",
    "spec",
    "output",
    "input",
    "file",
    "code"
  ]);
  const terms = new Set;
  const camelCase = requirements.match(/\b[A-Z][a-z]+[A-Z][a-zA-Z]*\b/g) || [];
  for (const term of camelCase) {
    if (term.length > 3)
      terms.add(term);
  }
  const allCaps = requirements.match(/\b[A-Z]{2,}[A-Z_]*\b/g) || [];
  for (const term of allCaps) {
    if (term.length > 2 && term !== "API" && term !== "TUI" && term !== "LLM")
      terms.add(term);
  }
  const words = requirements.toLowerCase().split(/[^a-z]+/);
  const wordCounts = {};
  for (const word of words) {
    if (word.length < 4 || STOP_WORDS.has(word))
      continue;
    wordCounts[word] = (wordCounts[word] || 0) + 1;
  }
  for (const [word, count] of Object.entries(wordCounts)) {
    if (count >= 2)
      terms.add(word);
  }
  const quoted = requirements.match(/"([^"]{3,30})"/g) || [];
  for (const q of quoted) {
    const inner = q.replace(/"/g, "").toLowerCase();
    if (inner.length > 3 && !STOP_WORDS.has(inner))
      terms.add(inner);
  }
  const result = [...terms].sort((a, b) => b.length - a.length).slice(0, 8);
  return result.length > 0 ? result : [];
}
